// Some portions generated by Codex

// @ts-check
const { test, expect } = require('@playwright/test');

const SERVER_BASE_URL = (process.env.RDF4J_SERVER_BASE_URL
	|| 'http://127.0.0.1:8091/rdf4j-server').replace(/\/+$/, '');
const WORKBENCH_BASE_URL = (process.env.RDF4J_WORKBENCH_BASE_URL
	|| 'http://127.0.0.1:8091/rdf4j-workbench').replace(/\/+$/, '');
const STREAM_ACCEPT = 'application/vnd.rdf4j.workbench-query-v2+ndjson';
let repositoryId;
let repositoryUrl;
let queryUrl;
let savedQueriesUrl;

test.beforeAll(async ({ request }, testInfo) => {
	repositoryId = `options-anchor-${testInfo.project.name}-${process.pid}-${Date.now().toString(36)}`;
	repositoryUrl = `${SERVER_BASE_URL}/repositories/${repositoryId}`;
	queryUrl = `${WORKBENCH_BASE_URL}/repositories/${repositoryId}/query`;
	savedQueriesUrl = `${WORKBENCH_BASE_URL}/repositories/${repositoryId}/saved-queries`;
	const existing = await request.get(repositoryUrl);
	if (![400, 404].includes(existing.status())) {
		throw new Error(`Refusing to use non-absent anchor fixture ${repositoryId}: GET ${existing.status()}`);
	}
	const created = await request.put(repositoryUrl, {
		headers: { 'Content-Type': 'text/turtle' },
		data: repositoryConfiguration(repositoryId)
	});
	expect([200, 201, 204]).toContain(created.status());
});

test.afterAll(async ({ request }) => {
	if (repositoryUrl) {
		const deleted = await request.delete(repositoryUrl).catch(() => null);
		if (deleted) {
			expect([200, 204, 400, 404]).toContain(deleted.status());
		}
	}
});

for (const surface of ['main query', 'saved query']) {
	test(`${surface} result disclosures stay anchored at mobile width after resize`, async ({ page }, testInfo) => {
		const streamedRequests = [];
		const pageErrors = [];
		page.on('request', request => {
			if (request.method() === 'POST' && /\/query(?:[?#]|$)/.test(request.url())
					&& (request.headers().accept || '').includes(STREAM_ACCEPT)) {
				streamedRequests.push(request.url());
			}
		});
		page.on('pageerror', error => pageErrors.push(error.message));

		const query = 'SELECT ?item WHERE { VALUES ?item { '
			+ Array.from({ length: 11 }, (_unused, index) => `"item-${String(index + 1).padStart(2, '0')}"`).join(' ')
			+ ' } } ORDER BY ?item';
		await page.setViewportSize({ width: 1440, height: 1000 });
		await page.goto(queryUrl, { waitUntil: 'domcontentloaded' });
		await page.locator('#query-form').waitFor({ state: 'visible', timeout: 15000 });
		await page.locator('.CodeMirror').first().waitFor({ state: 'visible' });
		await page.locator('.CodeMirror').first().evaluate((editor, value) => editor.CodeMirror.setValue(value), query);

		let result;
		if (surface === 'saved query') {
			const queryName = `anchor-${Date.now().toString(36)}`;
			await page.locator('#save-query-toggle').click();
			await page.locator('#query-name').fill(queryName);
			await page.evaluate(() => window.workbench.query.handleNameChange());
			const saveRequest = page.waitForRequest(request => request.method() === 'POST'
				&& /\/query(?:[?#]|$)/.test(request.url())
				&& new URLSearchParams(request.postData() || '').get('action') === 'save');
			await page.locator('#save').click();
			await saveRequest;
			await expect(page.locator('#save-feedback')).toHaveText('Query saved.');
			await page.goto(savedQueriesUrl, { waitUntil: 'domcontentloaded' });
			await page.locator('#saved-queries').waitFor({ state: 'visible' });
			const row = page.locator('.saved-query-row').filter({ hasText: queryName });
			await expect(row).toHaveCount(1);
			const form = row.locator('form[data-workbench-query-execution]');
			await form.locator('input[type="submit"]').click();
			const resultMount = row.locator('.query-results');
			await expect(resultMount).toHaveAttribute('aria-busy', 'false');
			result = row.locator('.query-results .query-result-layout');
		} else {
			await page.locator('#exec').click();
			const resultMount = page.locator('#query-results');
			await expect(resultMount).toHaveAttribute('aria-busy', 'false');
			result = page.locator('#query-results .query-result-layout');
		}

		await expect(result).toBeVisible();
		await page.setViewportSize({ width: 390, height: 844 });
		const measurements = [];
		for (const kind of ['download', 'options']) {
			const button = result.locator(`.query-result-${kind}-toggle`);
			await expect(button).toBeVisible();
			await button.scrollIntoViewIfNeeded();
			await button.click();
			await expect(button).toHaveAttribute('aria-expanded', 'true');
			const panelId = await button.getAttribute('aria-controls');
			expect(panelId).toBeTruthy();
			const panel = page.locator(`#${panelId}`);
			await expect(panel).toBeVisible();
			await settleDisclosure(panel);
			await panel.scrollIntoViewIfNeeded();
			await settleDisclosure(panel);
			const geometry = await button.evaluate(trigger => {
				const disclosure = document.getElementById(trigger.getAttribute('aria-controls'));
				const triggerRect = trigger.getBoundingClientRect();
				const panelRect = disclosure.getBoundingClientRect();
				return {
					triggerCenterX: (triggerRect.left + triggerRect.right) / 2,
					triggerBottom: triggerRect.bottom,
					panelLeft: panelRect.left,
					panelRight: panelRect.right,
					panelTop: panelRect.top,
					panelBottom: panelRect.bottom,
					arrowX: panelRect.left + parseFloat(disclosure.style.getPropertyValue('--workbench-disclosure-anchor-x')),
					viewportWidth: document.documentElement.clientWidth,
					viewportHeight: window.innerHeight
				};
			});
			measurements.push({ kind, ...geometry });
			expect(Number.isFinite(geometry.arrowX), `${kind} disclosure should expose its measured arrow`).toBe(true);
			expect(geometry.panelLeft, `${kind} panel should fit the mobile viewport on the left`).toBeGreaterThanOrEqual(0);
			expect(geometry.panelRight, `${kind} panel should fit the mobile viewport on the right`)
				.toBeLessThanOrEqual(geometry.viewportWidth);
			expect(geometry.panelTop, `${kind} panel should remain below its trigger`).toBeGreaterThanOrEqual(geometry.triggerBottom);
			expect(geometry.panelBottom, `${kind} panel should be reachable in the mobile viewport`)
				.toBeLessThanOrEqual(geometry.viewportHeight + 1);
			expect.soft(Math.abs(geometry.arrowX - geometry.triggerCenterX),
				`${surface} ${kind} disclosure arrow should align with its own trigger`).toBeLessThanOrEqual(1);
			if (kind === 'download') {
				await button.click();
				await expect(button).toHaveAttribute('aria-expanded', 'false');
				await settleDisclosure(panel);
			}
		}
		await testInfo.attach(`${surface.replaceAll(' ', '-')}-mobile-options.png`, {
			body: await page.screenshot({ animations: 'disabled' }),
			contentType: 'image/png'
		});
		await testInfo.attach(`${surface.replaceAll(' ', '-')}-mobile-disclosure-geometry.json`, {
			body: Buffer.from(JSON.stringify({ viewport: '390x844', measurements, streamedRequests, pageErrors }, null, 2)),
			contentType: 'application/json'
		});
		console.log(`[query-result-mobile-disclosures] ${JSON.stringify({ surface, measurements, queryCount: streamedRequests.length, pageErrors })}`);
		expect(streamedRequests).toHaveLength(1);
		expect(pageErrors).toEqual([]);
	});
}

async function settleDisclosure(panel) {
	await panel.evaluate(async element => {
		await Promise.all(element.getAnimations().map(animation => animation.finished.catch(() => undefined)));
		await new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));
	});
}

function repositoryConfiguration(id) {
	return `@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#>.
@prefix config: <tag:rdf4j.org,2023:config/>.
[] a config:Repository ;
   config:rep.id "${id}" ;
   rdfs:label "Workbench result disclosure anchor fixture" ;
   config:rep.impl [ config:rep.type "openrdf:SailRepository" ;
      config:sail.impl [ config:sail.type "openrdf:MemoryStore" ; config:mem.persist false ] ].`;
}
